public class Trie
{
    private class TrieNode
    {
        public readonly Dictionary<char, TrieNode> Children = new();
        public bool IsWord;
    }

    private readonly TrieNode _root = new();

    public void Insert(string word)
    {
        var node = _root;

        foreach (char c in word)
        {
            if (!node.Children.TryGetValue(c, out var next))
            {
                next = new TrieNode();
                node.Children[c] = next;
            }

            node = next;
        }

        node.IsWord = true;
    }

    public bool Search(string word) => Find(word)?.IsWord == true;

    public bool StartsWith(string prefix) => Find(prefix) != null;

    /// Walks the trie following the characters, returning the final node
    /// or null if the path does not exist.
    private TrieNode? Find(string s)
    {
        var node = _root;

        foreach (char c in s)
        {
            if (!node.Children.TryGetValue(c, out var next)) return null;
            node = next;
        }

        return node;
    }
}

public IReadOnlyList<string> WordsWithPrefix(string prefix)
{
    var result = new List<string>();
    var node = Find(prefix);

    if (node == null) return result;

    var buffer = new System.Text.StringBuilder(prefix);
    Collect(node, buffer, result);
    return result;
}

private static void Collect(TrieNode node, System.Text.StringBuilder buffer, List<string> output)
{
    if (node.IsWord) output.Add(buffer.ToString());

    foreach (var (c, child) in node.Children)
    {
        buffer.Append(c);
        Collect(child, buffer, output);
        buffer.Length--;
    }
}

public class Trie
{
    private class Node
    {
        public readonly Dictionary<char, Node> Children = new();
        public bool IsWord;
    }

    private readonly Node _root = new();

    public void Insert(string word)
    {
        var node = _root;
        foreach (char c in word)
        {
            if (!node.Children.TryGetValue(c, out var next))
            {
                next = new Node();
                node.Children[c] = next;
            }
            node = next;
        }
        node.IsWord = true;
    }

    public bool Search(string word) => Find(word)?.IsWord == true;
    public bool StartsWith(string prefix) => Find(prefix) != null;

    private Node? Find(string s)
    {
        var node = _root;
        foreach (char c in s)
        {
            if (!node.Children.TryGetValue(c, out var next)) return null;
            node = next;
        }
        return node;
    }
